"use client"

import { useState, useEffect } from "react"
import ChatInterface from "@/components/chat/ChatInterface"
import OutfitDetails from "@/components/outfit/OutfitDetails"
import { Button } from "@/components/ui/button"
import { NavigationFilters } from "@/components/navigation/NavigationFilters"
import { OutfitDiscovery } from "@/components/outfit/OutfitDiscovery"
import { ChatAssistant } from "@/components/chat/ChatAssistant"
import { OutfitDetail } from "@/components/outfit/OutfitDetail"
import { ResizablePanel } from "@/components/layout/ResizablePanel"
import { useOutfitDiscovery } from "@/lib/hooks/useOutfitDiscovery"
import { useOutfitCache } from "@/lib/hooks/useOutfitCache"
import { loadProducts, fetchOutfits } from "@/lib/services/outfit-service"
import type { Product, Outfit } from "@/lib/types"
import { getGenderSpecificUrl, getSimilarOutfits } from "@/lib/utils/product-utils"
import { initializeProductCatalog } from "@/lib/data-loader"
import { MessageCircle, Sparkles, Bell, SlidersHorizontal, Grid3x3 } from "lucide-react"
import { OnboardingFlow } from "@/components/onboarding/OnboardingFlow"
import { useUserProfile } from "@/lib/hooks/useUserProfile"

export default function HomePage() {
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null)
  const [isOutfitDetailsOpen, setIsOutfitDetailsOpen] = useState(false)
  const [activeTab, setActiveTab] = useState<"outfits" | "chat" | "filters">("outfits")
  const [products, setProducts] = useState<Product[]>([])
  const [allOutfits, setAllOutfits] = useState<Outfit[]>([])
  const [isLoadingProducts, setIsLoadingProducts] = useState(true)
  const [isLoadingOutfits, setIsLoadingOutfits] = useState(false)
  const [showOnboarding, setShowOnboarding] = useState(true)

  // User profile hook for onboarding
  const { profile, isLoading: isLoadingProfile } = useUserProfile()

  // Cache hook
  const { getFromCache, saveToCache } = useOutfitCache()

  // Check onboarding status after profile loads
  useEffect(() => {
    if (!isLoadingProfile) {
      // Only hide onboarding if profile exists AND onboarding is completed
      if (profile?.onboardingCompleted) {
        setShowOnboarding(false)
      }
      // If no profile or onboarding not completed, keep showOnboarding as true
    }
  }, [profile, isLoadingProfile])

  // Handle onboarding completion
  const handleOnboardingComplete = () => {
    setShowOnboarding(false)
  }

  // Load products on mount
  useEffect(() => {
    // Initialize product catalog (loads both legacy and enhanced products)
    initializeProductCatalog()
      .then(({ legacy, enhanced }) => {
        console.log(`[HomePage] Loaded ${legacy.length} legacy products, ${enhanced.length} enhanced products`)
        setProducts(legacy)
      })
      .catch(err => {
        console.error('Failed to load products:', err)
        // Fallback to old loadProducts method
        loadProducts()
          .then(setProducts)
          .catch(() => console.error('Failed to load products'))
      })
      .finally(() => setIsLoadingProducts(false))
  }, [])

  // Use centralized outfit discovery hook
  const {
    filters,
    setFilters,
    filteredOutfits,
    selectedOutfit,
    viewMode,
    selectOutfit,
    backToChat,
    resetFilters
  } = useOutfitDiscovery(allOutfits)

  // Generate outfits when products load or filters change
  useEffect(() => {
    if (products.length === 0) return

    // Check cache first
    const cached = getFromCache(filters)
    if (cached && cached.length > 0) {
      setAllOutfits(cached)
      return
    }

    setIsLoadingOutfits(true)

    fetchOutfits(products, filters, 50)
      .then(outfits => {
        setAllOutfits(outfits)
        saveToCache(filters, outfits)
      })
      .catch(err => {
        console.error('Failed to generate outfits:', err)
      })
      .finally(() => setIsLoadingOutfits(false))
  }, [products, filters, getFromCache, saveToCache])

  // Keyboard navigation support
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // ESC key to close product detail or outfit details
      if (e.key === "Escape") {
        if (selectedProduct) {
          setSelectedProduct(null)
        } else if (selectedOutfit) {
          backToChat()
        }
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [selectedProduct, selectedOutfit, backToChat])

  const handleProductClick = (product: Product) => {
    setSelectedProduct(product)
  }

  const handleShopLook = (outfit: Outfit) => {
    console.log("Shopping for outfit:", outfit.title)
  }

  const handleBuyProduct = (product: Product) => {
    const url = getGenderSpecificUrl(product)
    window.open(url, '_blank', 'noopener,noreferrer')
  }

  const handleBuyAll = () => {
    if (!selectedOutfit) return
    // Open first product's URL as default
    const firstProduct = selectedOutfit.items[0]
    if (firstProduct) {
      handleBuyProduct(firstProduct)
    }
  }

  const getSimilarOutfitsForSelected = (): Outfit[] => {
    if (!selectedOutfit) return []
    return getSimilarOutfits(selectedOutfit, filteredOutfits, 6)
  }

  // Desktop three-panel layout
  const renderDesktopLayout = () => (
    // Full-width responsive layout that expands to fill the viewport
    // - Left Panel: Fixed 280px width for consistent navigation experience
    // - Middle Panel: Flexible (flex-1) to take remaining space
    // - Right Panel: Fixed 420px width for chat/details
    // This ensures the layout always fills 100% viewport width without max-width constraints

    <div className="hidden lg:flex h-screen w-full">
      {/* Left Panel - Navigation & Filters */}
      <div className="w-[280px] flex-shrink-0">
        <NavigationFilters
          filters={filters}
          onFilterChange={setFilters}
          onResetFilters={resetFilters}
        />
      </div>

      {/* Middle Panel - Outfit Discovery (Flexible, takes remaining space) */}
      <main className="flex-1 min-w-0" aria-label="Outfit Recommendations">
        <OutfitDiscovery
          outfits={filteredOutfits}
          onSelectOutfit={selectOutfit}
          onClearFilters={resetFilters}
          isLoading={isLoadingProducts || isLoadingOutfits}
        />
      </main>

      {/* Right Panel - Resizable Chat Assistant + Details */}
      <ResizablePanel
        defaultWidth={420}
        minWidth={280}
        maxWidthPercent={50}
        className="border-l"
        ariaLabel="Chat and outfit details"
      >
        <div className={viewMode === "chat" ? "h-full" : "h-full hidden"}>
          <ChatAssistant onViewOutfit={selectOutfit} />
        </div>
        <div className={viewMode === "detail" && selectedOutfit ? "h-full" : "hidden"}>
          <OutfitDetail
            outfit={selectedOutfit}
            similarOutfits={getSimilarOutfitsForSelected()}
            onBack={backToChat}
            onBuyProduct={handleBuyProduct}
            onBuyAll={handleBuyAll}
            onSelectSimilar={selectOutfit}
          />
        </div>
      </ResizablePanel>
    </div>
  )

  // Mobile layout with bottom tabs
  const renderMobileLayout = () => (
    <div className="lg:hidden flex flex-col h-screen">
      {/* Header */}
      <header className="sticky top-0 z-header border-b bg-background">
        <div className="flex items-center justify-between px-5 py-4">
          <div className="flex items-center gap-3">
            <Sparkles className="w-7 h-7 text-primary" />
            <h1 className="text-xl font-bold">OOTDay</h1>
          </div>
          <Button variant="ghost" size="sm" className="h-10 w-10">
            <Bell className="w-5 h-5" />
          </Button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <div className={activeTab === "outfits" ? "block" : "hidden"}>
          <div className="p-5">
            <div className="grid grid-cols-2 gap-4">
              {filteredOutfits.map((outfit) => (
                <div
                  key={outfit.id}
                  className="cursor-pointer hover:shadow-lg transition-shadow border rounded-lg overflow-hidden"
                  onClick={() => selectOutfit(outfit)}
                >
                  <div className="aspect-[3/4] bg-gray-100"></div>
                  <div className="p-3">
                    <h3 className="font-medium text-sm line-clamp-1">{outfit.title}</h3>
                    <p className="text-primary font-bold text-sm mt-1">฿{outfit.totalPrice.toLocaleString()}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className={activeTab === "chat" ? "block h-full" : "hidden"}>
          <ChatInterface
            onOutfitSelect={(outfitId) => {
              const outfit = allOutfits.find(o => o.id === outfitId)
              if (outfit) selectOutfit(outfit)
            }}
            onViewDetails={selectOutfit}
          />
        </div>

        {activeTab === "filters" && (
          <NavigationFilters
            filters={filters}
            onFilterChange={setFilters}
            onResetFilters={resetFilters}
          />
        )}
      </main>

      {/* Bottom Navigation */}
      <nav className="border-t bg-background">
        <div className="flex items-center justify-around py-3">
          <Button
            variant="ghost"
            size="sm"
            className={`flex flex-col items-center gap-1.5 h-auto py-2 ${activeTab === "filters" ? "text-primary" : "text-gray-600"
              }`}
            onClick={() => setActiveTab("filters")}
          >
            <SlidersHorizontal className="w-6 h-6" />
            <span className="text-xs font-medium">กรอง</span>
          </Button>

          <Button
            variant="ghost"
            size="sm"
            className={`flex flex-col items-center gap-1.5 h-auto py-2 ${activeTab === "outfits" ? "text-primary" : "text-gray-600"
              }`}
            onClick={() => setActiveTab("outfits")}
          >
            <Grid3x3 className="w-6 h-6" />
            <span className="text-xs font-medium">ชุด</span>
          </Button>

          <Button
            variant="ghost"
            size="sm"
            className={`flex flex-col items-center gap-1.5 h-auto py-2 ${activeTab === "chat" ? "text-primary" : "text-gray-600"
              }`}
            onClick={() => setActiveTab("chat")}
          >
            <MessageCircle className="w-6 h-6" />
            <span className="text-xs font-medium">แชท</span>
          </Button>
        </div>
      </nav>
    </div>
  )

  // Show loading state while profile is being loaded
  if (isLoadingProfile) {
    return null // or a loading spinner if desired
  }

  // Show onboarding if user hasn't completed it
  if (showOnboarding) {
    return <OnboardingFlow onComplete={handleOnboardingComplete} />
  }

  // Show main app
  return (
    <>
      {renderDesktopLayout()}
      {renderMobileLayout()}

      {/* Outfit Details Modal - for mobile */}
      <OutfitDetails
        outfit={selectedOutfit}
        isOpen={isOutfitDetailsOpen}
        onClose={() => {
          setIsOutfitDetailsOpen(false)
          backToChat()
        }}
        onProductClick={handleProductClick}
        onShopLook={handleShopLook}
      />
    </>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import Image from 'next/image'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import type { Outfit } from '@/lib/types'
import { useUserProfile } from '@/lib/hooks/useUserProfile'
import { generateTryOnLooks } from '@/lib/services/fitting-model-service'
import { Eye, Heart, Share2, Shirt, Loader2, RefreshCw, AlertCircle } from 'lucide-react'

interface OutfitRecommendationCardProps {
  outfit: Outfit
  onViewOutfit: (outfit: Outfit) => void
}

export function OutfitRecommendationCard({
  outfit,
  onViewOutfit
}: OutfitRecommendationCardProps) {
  const [isLiked, setIsLiked] = useState(false)
  const [imageError, setImageError] = useState(false)

  // Try-on state
  const [showTryOnModal, setShowTryOnModal] = useState(false)
  const [isGeneratingTryOn, setIsGeneratingTryOn] = useState(false)
  const [tryOnImageUrl, setTryOnImageUrl] = useState<string | undefined>(outfit.tryOnImageUrl)
  const [tryOnImageBase64, setTryOnImageBase64] = useState<string | undefined>(outfit.tryOnImageBase64)
  const [tryOnError, setTryOnError] = useState<string | undefined>()

  // Get user profile for fitting model
  const { profile } = useUserProfile()

  // Check if user has a fitting model
  const hasFittingModel = !!profile?.fittingModelUrl

  // Determine image source: prefer flat-lay, fallback to product thumbnail
  const flatLayImage = outfit.flatLayImageUrl || outfit.flatLayImageBase64
  const fallbackImage = outfit.imageUrl
  const displayImage = flatLayImage || fallbackImage
  const isGenerating = outfit.isGeneratingFlatLay

  // Try-on image to display
  const tryOnImage = tryOnImageUrl || tryOnImageBase64

  // Sync with outfit prop when it changes
  useEffect(() => {
    if (outfit.tryOnImageUrl) {
      setTryOnImageUrl(outfit.tryOnImageUrl)
    }
    if (outfit.tryOnImageBase64) {
      setTryOnImageBase64(outfit.tryOnImageBase64)
    }
  }, [outfit.tryOnImageUrl, outfit.tryOnImageBase64])

  /**
   * Handle try-on button click
   */
  const handleTryOn = useCallback(async () => {
    // If we already have a try-on image, just open the modal
    if (tryOnImage) {
      setShowTryOnModal(true)
      return
    }

    // Check if user has a fitting model
    if (!hasFittingModel || !profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setShowTryOnModal(true)
      return
    }

    // Start generation
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)
    setShowTryOnModal(true)

    try {
      // Extract outfit items for the prompt
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [tryOnImage, hasFittingModel, profile?.fittingModelUrl, outfit])

  /**
   * Handle regenerate try-on image
   */
  const handleRegenerate = useCallback(async () => {
    // Clear current image and regenerate
    setTryOnImageUrl(undefined)
    setTryOnImageBase64(undefined)
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)

    if (!profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setIsGeneratingTryOn(false)
      return
    }

    try {
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Regenerate error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [profile?.fittingModelUrl, outfit])

  return (
    <>
      <Card className="p-3 bg-white/10 backdrop-blur-sm hover:bg-white/20 transition-colors overflow-hidden">
        {/* Flat-lay image area (square aspect ratio) */}
        <div className="relative w-full aspect-square bg-gray-100 rounded-lg overflow-hidden mb-3">
          {isGenerating ? (
            // Loading skeleton while flat-lay is generating
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <Skeleton className="w-full h-full absolute inset-0" />
              <div className="z-10 text-center px-4">
                <div className="flex justify-center mb-2">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                  </div>
                </div>
                <p className="text-xs text-gray-500">กำลังสร้างภาพ LOOKs...</p>
              </div>
            </div>
          ) : displayImage && !imageError ? (
            // Show flat-lay or fallback image
            <Image
              src={displayImage}
              alt={outfit.title}
              fill
              className={flatLayImage ? 'object-contain' : 'object-cover'}
              sizes="(max-width: 768px) 100vw, 400px"
              onError={() => setImageError(true)}
            />
          ) : (
            // Placeholder when no image available
            <div className="w-full h-full flex items-center justify-center bg-gray-200">
              <span className="text-gray-400 text-sm">No image</span>
            </div>
          )}
        </div>

        {/* Card content */}
        <div className="space-y-2">
          <div>
            <h4 className="font-semibold text-sm line-clamp-2">{outfit.title}</h4>
            <p className="text-xs text-muted-foreground mt-0.5">
              {outfit.items.length} ชิ้น
            </p>
          </div>

          <p className="text-base font-bold">
            ฿{outfit.totalPrice.toLocaleString()}
          </p>

          {/* Action Icons Row */}
          <div className="flex items-center gap-1.5">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => onViewOutfit(outfit)}
              className="flex-1 h-8 text-xs gap-1"
            >
              <Eye className="w-3.5 h-3.5" />
              ดูลุค
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={handleTryOn}
              disabled={isGeneratingTryOn}
              className="h-8 px-2 text-xs gap-1"
              aria-label="ลองใส่ outfit นี้"
              title={hasFittingModel ? 'ลองใส่' : 'กรุณาอัปโหลดรูปภาพก่อน'}
            >
              {isGeneratingTryOn ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Shirt className="w-3.5 h-3.5" />
              )}
              ลองใส่
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setIsLiked(!isLiked)}
              className="h-8 w-8 p-0"
              aria-label={isLiked ? "Unlike outfit" : "Like outfit"}
            >
              <Heart className={`w-4 h-4 ${isLiked ? "fill-red-500 text-red-500" : "text-gray-600"}`} />
            </Button>
            <Button
              size="sm"
              variant="ghost"
              className="h-8 w-8 p-0"
              aria-label="Share outfit"
            >
              <Share2 className="w-4 h-4 text-gray-600" />
            </Button>
          </div>
        </div>
      </Card>

      {/* Try-On Modal */}
      <Dialog open={showTryOnModal} onOpenChange={setShowTryOnModal}>
        <DialogContent className="max-w-md mx-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shirt className="w-5 h-5" />
              ลองใส่: {outfit.title}
            </DialogTitle>
            <DialogDescription>
              ดูชุดนี้บนโมเดลของคุณ
            </DialogDescription>
          </DialogHeader>

          {/* Try-On Image Area */}
          <div className="relative w-full aspect-[3/4] bg-gray-100 rounded-lg overflow-hidden">
            {isGeneratingTryOn ? (
              // Loading state
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <Skeleton className="w-full h-full absolute inset-0" />
                <div className="z-10 text-center px-4">
                  <div className="flex justify-center mb-3">
                    <Loader2 className="w-8 h-8 text-primary animate-spin" />
                  </div>
                  <p className="text-sm text-gray-600 font-medium">กำลังสร้างรูปภาพ...</p>
                  <p className="text-xs text-gray-400 mt-1">อาจใช้เวลา 10-30 วินาที</p>
                </div>
              </div>
            ) : tryOnError ? (
              // Error state
              <div className="absolute inset-0 flex flex-col items-center justify-center p-4">
                <div className="text-center">
                  <AlertCircle className="w-12 h-12 text-red-400 mx-auto mb-3" />
                  <p className="text-sm text-gray-600 mb-4">{tryOnError}</p>
                  {hasFittingModel && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={handleRegenerate}
                      className="gap-2"
                    >
                      <RefreshCw className="w-4 h-4" />
                      ลองอีกครั้ง
                    </Button>
                  )}
                </div>
              </div>
            ) : tryOnImage ? (
              // Show try-on image
              <Image
                src={tryOnImage}
                alt={`ลองใส่: ${outfit.title}`}
                fill
                className="object-contain"
                sizes="(max-width: 768px) 100vw, 400px"
              />
            ) : (
              // Empty state (should not happen normally)
              <div className="w-full h-full flex items-center justify-center bg-gray-200">
                <span className="text-gray-400 text-sm">ไม่มีรูปภาพ</span>
              </div>
            )}
          </div>

          {/* Action buttons */}
          <div className="flex gap-2 mt-2">
            {tryOnImage && !isGeneratingTryOn && (
              <Button
                size="sm"
                variant="outline"
                onClick={handleRegenerate}
                className="flex-1 gap-2"
              >
                <RefreshCw className="w-4 h-4" />
                ลองใส่ใหม่
              </Button>
            )}
            <Button
              size="sm"
              variant="default"
              onClick={() => setShowTryOnModal(false)}
              className="flex-1"
            >
              ปิด
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import { useSearchParams, useRouter, usePathname } from 'next/navigation'
import type { Outfit, FilterState } from '@/lib/types'
import { filterOutfits } from '@/lib/utils/outfit-filter'
import { parseFiltersFromUrl, filtersToUrlParams } from '@/lib/utils/url-params'
import { useUserProfile } from '@/lib/hooks/useUserProfile'

export function useOutfitDiscovery(allOutfits: Outfit[]) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const { profile } = useUserProfile()

  // Initialize state from URL with user profile fallback
  const [filters, setFilters] = useState<FilterState>(() =>
    parseFiltersFromUrl(searchParams, profile?.gender)
  )

  const [selectedOutfit, setSelectedOutfit] = useState<Outfit | null>(null)
  const [viewMode, setViewMode] = useState<'chat' | 'detail'>('chat')

  // Sync gender filter with user profile when profile loads
  // Priority: URL params > user manual selection > profile preference
  useEffect(() => {
    const urlGender = searchParams.get('gender')
    // Only sync if: no URL gender param, profile is loaded, and filter is currently 'all'
    if (!urlGender && profile && filters.gender === 'all') {
      setFilters(prev => ({ ...prev, gender: profile.gender }))
    }
  }, [profile, searchParams])

  // Load selected outfit from URL on mount
  useEffect(() => {
    const outfitId = searchParams.get('outfit')
    if (outfitId) {
      const outfit = allOutfits.find(o => o.id === outfitId)
      if (outfit) {
        setSelectedOutfit(outfit)
        setViewMode('detail')
      }
    }
  }, []) // Run only on mount

  // Memoized filtered outfits
  const filteredOutfits = useMemo(() => {
    return filterOutfits(allOutfits, filters)
  }, [allOutfits, filters])

  // Sync URL with state (debounced to avoid excessive updates)
  useEffect(() => {
    const params = filtersToUrlParams(filters, selectedOutfit?.id)
    const newUrl = params ? `${pathname}?${params}` : pathname

    // Only update if URL actually changed
    const currentUrl = `${pathname}${searchParams.toString() ? '?' + searchParams.toString() : ''}`
    if (newUrl !== currentUrl) {
      window.history.pushState({}, '', newUrl)
    }
  }, [filters, selectedOutfit, pathname])

  // Handlers
  const selectOutfit = (outfit: Outfit) => {
    setSelectedOutfit(outfit)
    setViewMode('detail')
  }

  const backToChat = () => {
    setSelectedOutfit(null)
    setViewMode('chat')
  }

  const resetFilters = () => {
    setFilters({
      gender: profile?.gender || 'all',
      occasion: [],
      priceRange: { min: 0, max: 20000 },
      searchQuery: ''
    })
  }

  return {
    filters,
    setFilters,
    filteredOutfits,
    selectedOutfit,
    viewMode,
    selectOutfit,
    backToChat,
    resetFilters
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { ChatHeader } from './ChatHeader'
import { ChatMessage } from './ChatMessage'
import { ChatInput } from './ChatInput'
import { QuickPrompts } from './QuickPrompts'
import { OutfitRecommendationCard } from './OutfitRecommendationCard'
import { InteractiveTestMode } from './InteractiveTestMode'
import { Button } from '@/components/ui/button'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import { Beaker } from 'lucide-react'
import type { ChatMessage as ChatMessageType, Outfit, FlatLayItem, Product } from '@/lib/types'
import {
  findReplacementsForInconsistentProducts,
  validateProductVisualConsistency,
} from '@/lib/utils/product-visual-validator'
import type { TestResult } from '@/lib/types/test-types'
import { getMockOutfitResponse } from '@/lib/mock-data'
import { exportResultsBoth } from '@/lib/test-result-exporter'
import type { SessionContext } from '@/lib/types/chat-types'
import { createSessionContext } from '@/lib/utils/session-context'
import { useUserProfile } from '@/lib/hooks/useUserProfile'

interface ChatAssistantProps {
  onViewOutfit: (outfit: Outfit) => void
}

export function ChatAssistant({ onViewOutfit }: ChatAssistantProps) {
  const [messages, setMessages] = useState<ChatMessageType[]>([])
  const [isTyping, setIsTyping] = useState(false)
  const [testMode, setTestMode] = useState(false)

  // v2.0: Session context for duplicate prevention
  const [sessionContext, setSessionContext] = useState<SessionContext>(() => createSessionContext())
  const [conversationId] = useState<string>(() => `conv-${Date.now()}`)

  // v2.4: User profile for gender preference
  const { profile } = useUserProfile()

  // v3.1: Image generation state (Customer Journey Step 4)
  const [generatingImage, setGeneratingImage] = useState(false)
  const [imageGenerationError, setImageGenerationError] = useState<string | null>(null)

  // v8.0: All products for visual consistency replacement lookup
  const [allProducts, setAllProducts] = useState<Product[]>([])

  // v3.2: Initialize with Thai greeting message
  useEffect(() => {
    if (messages.length === 0) {
      const greeting: ChatMessageType = {
        id: 'greeting-initial',
        content: 'ฮ้ายฮายย👋 กำลังหาชุดไปไหนอยู่น้าา',
        sender: 'assistant',
        timestamp: new Date(),
      }
      setMessages([greeting])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  const isTestModeEnabled = process.env.NEXT_PUBLIC_ENABLE_TEST_MODE === 'true'

  /**
   * v8.0: Apply product replacements to an outfit for visual consistency
   * Creates a new outfit with items array where mismatched items are replaced
   * Recalculates totalPrice based on replacement prices
   */
  const applyProductReplacements = useCallback((
    outfit: Outfit,
    replacements: Map<string, Product>
  ): Outfit => {
    if (replacements.size === 0) return outfit

    const updatedItems = outfit.items.map(item => {
      const replacement = replacements.get(item.sku)
      return replacement || item
    })

    // Recalculate total price
    const newTotalPrice = updatedItems.reduce((sum, item) => sum + (item.price || 0), 0)

    return {
      ...outfit,
      items: updatedItems,
      totalPrice: newTotalPrice,
    }
  }, [])

  const handleTestComplete = (result: TestResult) => {
    console.log('Test completed:', result)
  }

  const handleExportResults = (results: TestResult[]) => {
    exportResultsBoth(results)
  }

  /**
   * v5.0: Generate flat-lay image for an outfit and update the message
   * v8.0: Enhanced with visual consistency validation and product replacement
   *
   * This function:
   * 1. Validates visual consistency between product text and thumbnails
   * 2. Replaces visually inconsistent products with consistent alternatives
   * 3. Generates flat-lay image using the corrected products
   * 4. Updates both the flat-lay image AND the product list in the message
   */
  const generateFlatLayForOutfit = useCallback(async (
    outfit: Outfit,
    messageId: string,
    productCatalog?: Product[]
  ) => {
    console.log(`[Chat] Generating flat-lay for outfit ${outfit.id}...`)

    // v8.0: Check for visual inconsistencies and find replacements if catalog provided
    let effectiveOutfit = outfit
    let replacementsMade = new Map<string, Product>()

    if (productCatalog && productCatalog.length > 0) {
      const replacementResult = findReplacementsForInconsistentProducts(
        outfit.items,
        productCatalog,
        { targetGender: 'women' }
      )

      if (replacementResult.replacements.size > 0) {
        console.log(
          `[Chat] Replacing ${replacementResult.replacements.size} visually inconsistent products in outfit ${outfit.id}:`,
          Array.from(replacementResult.replacements.entries()).map(([origSku, replacement]) => ({
            original: origSku,
            replacement: replacement.sku,
            name: replacement.name,
          }))
        )

        // Apply replacements to create the effective outfit
        effectiveOutfit = applyProductReplacements(outfit, replacementResult.replacements)
        replacementsMade = replacementResult.replacements

        // Update the message with corrected product list BEFORE generating flat-lay
        // This ensures the product thumbnails shown match the flat-lay image
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      }

      if (replacementResult.unreplaceableSkus.length > 0) {
        console.warn(
          `[Chat] ${replacementResult.unreplaceableSkus.length} items in outfit ${outfit.id} have visual mismatches but no replacement found:`,
          replacementResult.unreplaceableSkus
        )
      }
    }

    // Extract FlatLayItem array from effective outfit items (with replacements applied)
    const flatLayItems: FlatLayItem[] = effectiveOutfit.items.slice(0, 5).map((item: Product) => ({
      name: item.name,
      category: item.subCategory || item.category || 'Item',
      color: item.colors?.[0],
      visualDescription: item.visualDescription,
    }))
    const occasionContext = outfit.description

    if (flatLayItems.length === 0) {
      console.log('[Chat] No items to generate flat-lay for')
      return
    }

    try {
      const imageResponse = await fetch('/api/generate-image', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          description: outfit.description || 'LOOKs Inspiration',
          generationType: 'flat-lay',
          flatLayItems,
          occasionContext,
        }),
      })

      const imageData = await imageResponse.json()

      if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
        console.log(`[Chat] Flat-lay generated successfully for outfit ${outfit.id}`)

        // Update the message's outfit with the flat-lay image
        // Note: Product items were already updated above if replacements were made
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        flatLayImageUrl: imageData.imageUrl,
                        flatLayImageBase64: imageData.imageBase64,
                        isGeneratingFlatLay: false,
                        // Ensure items are the effective items (with replacements)
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      } else {
        console.error('[Chat] Flat-lay generation failed:', imageData.message)
        // Mark as not generating (will show fallback thumbnail)
        // Still apply any product replacements even if image generation failed
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        isGeneratingFlatLay: false,
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      }
    } catch (error) {
      console.error('[Chat] Flat-lay generation error:', error)
      // Mark as not generating on error
      // Still apply any product replacements even if image generation failed
      setMessages((prev) =>
        prev.map((msg) => {
          if (msg.id === messageId && msg.outfits) {
            return {
              ...msg,
              outfits: msg.outfits.map((o) =>
                o.id === outfit.id
                  ? {
                      ...o,
                      isGeneratingFlatLay: false,
                      items: effectiveOutfit.items,
                      totalPrice: effectiveOutfit.totalPrice,
                    }
                  : o
              ),
            }
          }
          return msg
        })
      )
    }
  }, [applyProductReplacements])

  const handleSendMessage = async (content: string) => {
    if (!content.trim()) return

    // Add user message
    const userMessage: ChatMessageType = {
      id: `user-${Date.now()}`,
      content: content.trim(),
      sender: 'user',
      timestamp: new Date(),
    }

    setMessages((prev) => [...prev, userMessage])
    setIsTyping(true)

    try {
      // Call real chat API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: content.trim(),
          conversationHistory: messages.map((msg) => ({
            role: msg.sender === 'user' ? 'user' : 'assistant',
            content: msg.content,
          })),
          sessionContext, // v2.0: Send current session context
          conversationId, // v2.0: Send conversation ID
          userPreferences: {
            gender: profile?.gender as 'men' | 'women' | undefined,
            userName: profile?.userName,
            ageRange: profile?.ageRange,
            stylePreferences: profile?.stylePreferences,
          }, // v2.5: Pass detailed profile info
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to get response from chat API')
      }

      const data = await response.json()

      // v2.0: Update session context if returned
      if (data.sessionContext) {
        setSessionContext(data.sessionContext)
        console.log(`[Chat] Session updated: ${data.sessionContext.recommendedProductIds?.length || 0} total products recommended`)
      }

      // v8.0: Collect all products from outfits for visual consistency replacement lookup
      const outfitProducts: Product[] = (data.outfits || []).flatMap((o: Outfit) => o.items || [])
      if (outfitProducts.length > 0) {
        setAllProducts(prev => {
          // Merge with existing products, avoiding duplicates by SKU
          const existingSkus = new Set(prev.map(p => p.sku))
          const newProducts = outfitProducts.filter((p: Product) => !existingSkus.has(p.sku))
          return [...prev, ...newProducts]
        })
      }

      // v5.0: Mark outfits as generating flat-lay if we have image request
      const outfitsWithLoading = (data.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: data.imageRequest && outfit.items.length > 0,
      }))

      // Create AI response message
      const messageId = `ai-${Date.now()}`
      const aiResponse: ChatMessageType = {
        id: messageId,
        content: data.message || 'สวัสดีค่ะ! นี่คือคำแนะนำสำหรับคุณ',
        sender: 'assistant',
        timestamp: new Date(),
        outfits: outfitsWithLoading,
      }

      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v5.0: Generate flat-lay images for each outfit (embedded in card, no separate message)
      if (data.imageRequest && outfitsWithLoading.length > 0) {
        console.log('[Chat] Image request detected, generating flat-lay for outfit cards...')

        // Add AI acknowledgment message for generation
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        // Generate flat-lay for each outfit, passing allProducts for visual consistency replacement
        for (const outfit of outfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId, allProducts)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    } catch (error) {
      console.error('Chat error:', error)

      // Fallback to mock response on error
      const aiResponse = getMockOutfitResponse(content)
      const messageId = `ai-mock-${Date.now()}`

      // v5.0: Mark mock outfits as generating flat-lay
      const mockOutfitsWithLoading = (aiResponse.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: outfit.items.length > 0,
      }))

      const mockMessage: ChatMessageType = {
        ...aiResponse,
        id: messageId,
        outfits: mockOutfitsWithLoading,
      }

      setMessages((prev) => [...prev, mockMessage])
      setIsTyping(false)

      // v5.0: Auto-generate flat-lay for mock responses
      if (mockOutfitsWithLoading.length > 0) {
        console.log('[Chat] Fallback: Auto-generating flat-lay for mock response...')

        // Add acknowledgement
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        for (const outfit of mockOutfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId, allProducts)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    }
  }

  return (
    <div className="h-full flex flex-col">
      {/* Test Mode Header */}
      {isTestModeEnabled && (
        <div className={`border-b px-4 py-3 flex items-center justify-between ${testMode ? 'bg-orange-50' : ''}`}>
          <div className="flex items-center gap-2">
            {testMode && (
              <span className="px-3 py-1 bg-orange-500 text-white font-bold rounded-md text-sm flex items-center gap-1">
                <Beaker className="w-4 h-4" />
                TEST MODE
              </span>
            )}
            <span className="text-sm text-muted-foreground">
              {testMode ? 'LLM Model Testing Interface' : 'OOTDay Stylist'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
            <Button
              size="sm"
              variant={testMode ? "primary" : "outline"}
              onClick={() => setTestMode(!testMode)}
              className={testMode ? "bg-orange-600 hover:bg-orange-700" : ""}
            >
              <Beaker className="w-4 h-4 mr-2" />
              {testMode ? 'Exit Test Mode' : 'Test Mode'}
            </Button>
          </div>
        </div>
      )}

      {/* Regular Header with resize controls */}
      {!isTestModeEnabled && !testMode && (
        <div className="border-b px-4 py-3 flex items-center justify-between">
          <span className="text-sm font-medium">OOTDay Stylist</span>
          {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
        </div>
      )}

      {/* Interactive Test Mode - Full Screen */}
      {testMode && isTestModeEnabled && (
        <div className="flex-1 overflow-hidden">
          <InteractiveTestMode onExport={handleExportResults} />
        </div>
      )}

      {!testMode && <ChatHeader />}

      {/* Messages Area */}
      {!testMode && (
        <div className="flex-1 overflow-y-auto px-4 py-3">
          {messages.length === 0 && (
            <div className="text-center py-8">
              <p className="text-sm text-muted-foreground leading-relaxed max-w-xs mx-auto">
                สวัสดีค่ะ! OOTDay Stylist พร้อมช่วยหาลุคที่ใช่สำหรับคุณค่ะ ✨
              </p>
            </div>
          )}

          {messages.map((message) => (
            <div key={message.id}>
              <ChatMessage message={message} />

              {/* Outfit recommendations with embedded flat-lay images */}
              {message.outfits && message.outfits.length > 0 && (
                <div className="ml-10 mt-2 space-y-2">
                  {message.outfits.map((outfit) => (
                    <OutfitRecommendationCard
                      key={outfit.id}
                      outfit={outfit}
                      onViewOutfit={onViewOutfit}
                    />
                  ))}
                </div>
              )}
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start">
              <div className="flex items-center gap-2 bg-gray-100 rounded-lg px-3 py-2">
                <div className="flex space-x-1">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Quick Prompts */}
      {!testMode && <QuickPrompts onPromptClick={handleSendMessage} />}

      {/* Chat Input */}
      {!testMode && <ChatInput onSend={handleSendMessage} disabled={isTyping} />}
    </div>
  )
}

